# Generated by build.py from recipe.yml for recipe socks5-keep-passwords-out-of-the-proxy-log. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--user', 'app:s3cret-pw', '--allow-plaintext-auth', 'http://localhost:8080/', 'ftp://localhost:8081/' -PassThru -NoNewWindow
$server1 = Start-Process surl -ArgumentList 'socks5h://127.0.0.1:8082/', '-v', '--log-file', 'proxy.log' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -x socks5h://127.0.0.1:8082 -u app:s3cret-pw ftp://localhost:8081/hello.txt } finally { Stop-Process $server0; Stop-Process $server1 }
